field_declarations.declaration:
struct OriginalArtifactNotice<'a> {
    schema_version: u32,
    purpose: &'static str,
    phase: &'a str,
    original_decision_head: [u8; 32],
}

pub(super) struct PinnedFileData {
    pub path: PathBuf,
    pub sha256: [u8; 32],
}

pub(super) enum OriginalFileMode {
    CreateNew,
    ExistingEmpty,
    Recover,
}

pub(super) struct MutableFileData {
    pub path: PathBuf,
    pub mode: OriginalFileMode,
}

pub(super) struct TrustData {
    pub scope_digest: [u8; 32],
    pub objective_digest: [u8; 32],
    pub authority_epoch: u64,
    pub signers: Vec<SignerData>,
}

pub(super) struct LearningAuthorityData {
    pub root: TrustRootData,
    pub signed: SignedTrustData,
    pub expected_distribution_digest: [u8; 32],
}

pub(in crate::same_actor_q24_deployment) enum OriginalLocalPolicyData {
    AdoptQualified,
    RetainCurrent,
    DeferQualified,
}

pub(super) enum OriginalPrivateHeadData {
    Drive { index: u16 },
    Prediction { index: u16 },
}

pub(super) struct OriginalInhibitoryEdgeData {
    pub source: usize,
    pub target: usize,
    pub weight_q24: i64,
}

pub(super) struct OriginalCandidateData {
    pub candidate_id: String,
    pub activation_index: usize,
    pub kind: OriginalCandidateKindData,
}

pub(super) struct OriginalTrainingLineageData {
    pub source_bundle: [u8; 32],
    pub dataset: [u8; 32],
    pub update_rule: [u8; 32],
    pub evaluation_profile: [u8; 32],
}

pub(super) struct OriginalCircuitRouteData {
    pub candidate_id: String,
    pub outcome: CircuitExitV2,
    pub selected_edges: Vec<String>,
}

pub(super) struct OriginalSelectionData {
    pub signed: OriginalDeploymentSelectionData,
    pub registry_snapshot: PinnedFileData,
    pub payload: PinnedFileData,
}

pub(super) struct OriginalArtifactOwnerData {
    pub root: PathBuf,
    pub trust: OriginalDeploymentOwnerTrustData,
    pub writer_lease: OriginalArtifactWriterData,
    // This is mandatory original Root-approved history. It is never inferred
    // from the files which are being opened and cannot silently become None.
    pub required_current_head: OriginalDeploymentCurrentData,
    pub withdrawal_file: PinnedFileData,
    pub withdrawal: OriginalDeploymentWithdrawalData,
    pub storage_binding: [u8; 32],
    pub selector: OriginalDeploymentSelectorTrustData,
    pub initial_selection: OriginalSelectionData,
}

pub(super) enum OriginalArtifactDecisionData {
    RetainOriginal,
    PublishQualified(Box<OriginalArtifactPublicationData>),
}

pub(super) struct OriginalActorExchangeData {
    pub request: MutableFileData,
    pub response: PathBuf,
}

pub(super) struct OriginalCapacityData {
    pub total_parameters: u64,
    pub trainable_parameters: u64,
    pub maximum_active_parameters: u64,
}

pub(super) struct OriginalSelectiveUpdateData {
    pub policy_digest: [u8; 32],
    pub eligibility_digest: [u8; 32],
    pub schedule_digest: [u8; 32],
    pub maximum_parameters_per_step: u64,
}

pub(super) enum OriginalCostMetricData {
    Wall, Cpu, Energy, StorageRead, StorageWrite, StorageRetention, Communication,
}

pub(super) struct OriginalComparisonData {
    pub candidate: OriginalTrainingObservationData,
    pub fixed_expert: OriginalTrainingObservationData,
    pub metering_contract_digest: [u8; 32],
    pub required_metrics: Vec<OriginalCostMetricData>,
}

pub(super) enum OriginalMetricRoleData {
    PrimarySuperiority { minimum_improvement_q32: i64 },
    NonInferiority { maximum_regression_q32: i64 },
    AbsoluteConstraint,
}

pub(super) struct OriginalQualificationContextData {
    pub generator: PrincipalData,
    pub evaluator: PrincipalData,
    pub retention_receipt_digests: Vec<[u8; 32]>,
    pub unlearning_receipt_digest: [u8; 32],
}

struct OriginalExecutionResponseData {
    schema_version: u32,
    request_digest: [u8; 32],
    execution_digest: [u8; 32],
    signed: SignedEvidenceData,
}

pub(super) struct OriginalEvaluationJournalData {
    pub journal: MutableFileData,
    pub witness: OriginalWitnessData,
    pub observer: OriginalDeploymentObserverData,
}

pub(super) struct OriginalHoldoutMinimumData {
    pub fence_generation: u64,
    pub record_count: u64,
    pub state_digest: [u8; 32],
}

pub(super) struct OriginalExecutionMinimumData {
    pub sequence: u64,
    pub history_digest: [u8; 32],
}

pub(super) struct OriginalEvaluationStoreData {
    pub file: MutableFileData,
    pub binding: [u8; 32],
    #[serde(deserialize_with = "required_option")]
    pub minimum: Option<OriginalExecutionMinimumData>,
}

pub(super) struct OriginalACompletionData {
    pub schema_version: u32,
    pub phase: String,
    pub outcome: OriginalSignedOutcomeData,
    pub preparation: OriginalPreparationData,
}

pub(super) struct OriginalCOutcomeData {
    pub schema_version: u32,
    pub phase: String,
    pub outcome: OriginalSignedOutcomeData,
}

pub(super) struct OriginalEvaluationResponse {
    pub schema_version: u32,
    pub request_digest: [u8; 32],
    pub original: OriginalEvaluationData,
}

pub(super) struct OriginalArtifactResponse {
    pub schema_version: u32,
    pub request_digest: [u8; 32],
    pub original: OriginalArtifactDecisionData,
}

pub(super) struct OriginalSelectionResponse {
    pub schema_version: u32,
    pub request_digest: [u8; 32],
    pub original: OriginalSelectionData,
}

pub(super) struct OriginalMaterialReady {
    pub schema_version: u32,
    pub request_digest: [u8; 32],
    pub material_digest: [u8; 32],
}
